        mutableClock().advanceMillis(60_000L);
        assert409(() -> service.confirm(r2.reservationId(), new ReservationActionRequest("req-e1")));
        ActivityHoursResponse.HourEntry afterExpire = hourEntry("act-1", DAY, 10);
